import{_ as a,o as r,c as t,a6 as i}from"./chunks/framework.DNkVJs23.js";const f=JSON.parse('{"title":"سياسة الخصوصية","description":"سياسة الخصوصية — Sapphire Star Codex","frontmatter":{"description":"سياسة الخصوصية — Sapphire Star Codex","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/ar/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/ar/privacy/"}],["meta",{"property":"og:title","content":"سياسة الخصوصية | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"سياسة الخصوصية — Sapphire Star Codex"}]]},"headers":[],"relativePath":"ar/privacy/index.md","filePath":"ar/privacy/index.md"}'),o={name:"ar/privacy/index.md"};function n(p,e,l,h,c,s){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="سياسة-الخصوصية" tabindex="-1">سياسة الخصوصية <a class="header-anchor" href="#سياسة-الخصوصية" aria-label="Permalink to &quot;سياسة الخصوصية&quot;">​</a></h1><p>تاريخ السريان: 31 أكتوبر 2026. آخر تحديث للنص الأصلي: 10 نوفمبر 2026. تاريخ الترجمة: 14 نوفمبر 2026.</p><p>تنطبق هذه السياسة على تطبيقات Sapphire Star Codex لنظامي iOS وAndroid ونظام HarmonyOS، وعلى هذا الموقع. المطوّر: <strong>eurekaffeine (刘耀晨)</strong>. للتواصل: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. تختلف الميزات بحسب المنصة، ولا يلزم إنشاء حساب.</p><h2 id="البيانات-المحلية" tabindex="-1">البيانات المحلية <a class="header-anchor" href="#البيانات-المحلية" aria-label="Permalink to &quot;البيانات المحلية&quot;">​</a></h2><p>يحفظ التطبيق على الجهاز تفضيلات اللعبة واللغة والمظهر، وسجل البحث وحالة التصفح، والمفضلة، وتشكيلات الدروع وأسماءها، ومخزون الزينات والتعاويذ والدروع. تُستخدم هذه البيانات لتقديم ميزات التطبيق ولا تُرفع إلى المطوّر. لا يشغّل المطوّر خدمة حسابات أو مزامنة سحابية.</p><h2 id="الأذونات-والجمع-التلقائي" tabindex="-1">الأذونات والجمع التلقائي <a class="header-anchor" href="#الأذونات-والجمع-التلقائي" aria-label="Permalink to &quot;الأذونات والجمع التلقائي&quot;">​</a></h2><p>لا يحتوي التطبيق على حزم برمجية للإعلانات أو التتبع أو إحصاءات الاستخدام أو إرسال تقارير الأعطال تلقائيًا. لا تتطلب الميزات الحالية الوصول إلى جهات الاتصال أو الموقع أو الكاميرا أو الميكروفون أو الصور، ولا تجمع معرّفات الإعلانات. قد تعالج أنظمة التشغيل والمتاجر بيانات التثبيت أو التشخيص وفق سياساتها. يستخدم المطوّر بيانات التشخيص التي توفرها المنصات لحل المشكلات فقط.</p><h2 id="التواصل-والخدمات-الخارجية" tabindex="-1">التواصل والخدمات الخارجية <a class="header-anchor" href="#التواصل-والخدمات-الخارجية" aria-label="Permalink to &quot;التواصل والخدمات الخارجية&quot;">​</a></h2><p>عند إرسال بريد طوعي، يتلقى المطوّر عنوانك والرسالة والمرفقات للرد والتحقيق في المشكلات ومعالجة طلبات الخصوصية، وليس للتسويق. أرسل المعلومات الضرورية فقط. يعالج Gmail البريد وفق <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">سياسة Google</a>.</p><p>يستضيف GitHub Pages هذا الموقع وقد يتلقى عنوان IP ومعلومات تقنية عن المتصفح؛ راجع <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">بيان GitHub</a>. لا تُضاف تحليلات للزيارات أو ملفات تعريف ارتباط إعلانية أو وحدات بكسل للتتبع. يعمل البحث داخل المتصفح، الذي قد يحفظ التفضيلات. تطبق الخدمات الخارجية سياساتها الخاصة وقد تعالج المعلومات خارج بلدك.</p><h2 id="المساهمات-والنسخ-الاحتياطية" tabindex="-1">المساهمات والنسخ الاحتياطية <a class="header-anchor" href="#المساهمات-والنسخ-الاحتياطية" aria-label="Permalink to &quot;المساهمات والنسخ الاحتياطية&quot;">​</a></h2><p>تعالج Alipay أو WeChat Pay المساهمات وفق شروطها. يعرض الموقع رموزًا ثابتة فقط، دون حزمة دفع برمجية أو تلقي بيانات اعتماد الدفع. قد يرى المطوّر المعلومات التي تعرضها المنصة للمستلم، مثل المبلغ والوقت والاسم الظاهر والملاحظة، للتحقق من المساهمات وحل المشكلات. تخضع مدة الاحتفاظ لقواعد المنصة والالتزامات المعمول بها. بحسب إعدادات النظام، قد تدخل بيانات التطبيق في نسخ احتياطية للجهاز أو السحابة؛ ولا يستطيع المطوّر قراءة تلك النسخ أو حذفها.</p><h2 id="المشاركة-والاحتفاظ-والحذف" tabindex="-1">المشاركة والاحتفاظ والحذف <a class="header-anchor" href="#المشاركة-والاحتفاظ-والحذف" aria-label="Permalink to &quot;المشاركة والاحتفاظ والحذف&quot;">​</a></h2><p>لا يبيع المطوّر المعلومات الشخصية أو يؤجرها أو يشاركها للإعلانات. يعالج مزوّد الخدمة المذكور البريد. يمكن تقديم المعلومات المحتفَظ بها فعليًا عند وجود التزام قانوني أو طلب صريح من المستخدم.</p><p>يمكن حذف البيانات المحلية عبر التطبيق أو إعدادات النظام. إزالة التطبيق مع الاحتفاظ ببياناته لا تمحوها؛ ويجب إدارة النسخ الاحتياطية بصورة منفصلة لأنها قد تستعيد البيانات. تبقى تفضيلات الموقع إلى أن تمحوها أو ينظفها المتصفح. تُحفظ الرسائل فقط للمعالجة أو المتابعة أو الالتزامات القانونية. يدير المزوّدون سجلاتهم ونسخهم الخاصة. تواصل لطلب الوصول إلى المعلومات المرسلة أو تصحيحها أو حذفها، مع مراعاة التزامات الاحتفاظ القانونية. لا يستطيع المطوّر الوصول عن بُعد إلى بيانات بقيت على الجهاز فقط.</p><h2 id="الأمان-والقاصرون-والتحديثات" tabindex="-1">الأمان والقاصرون والتحديثات <a class="header-anchor" href="#الأمان-والقاصرون-والتحديثات" aria-label="Permalink to &quot;الأمان والقاصرون والتحديثات&quot;">​</a></h2><p>تحمي آليات تخزين نظام التشغيل البيانات المحلية. يستخدم الموقع HTTPS. يقتصر الوصول إلى الرسائل على الدعم وطلبات الخصوصية، مع استخدام وسائل حماية مزوّد البريد. لا يطلب التطبيق ملفًا شخصيًا أو تاريخ ميلاد ولا يجمع عمدًا معلومات الأطفال. يمكن لولي الأمر طلب حذف معلومات أرسلها طفل.</p><p>تُحدَّث السياسة وتاريخها عند تغير ممارسات المعالجة. تُعلن التغييرات المهمة على الموقع أو في تحديثات التطبيق. تُطلب الأذونات أو الموافقات اللازمة للميزات الجديدة بصورة منفصلة؛ ولا تشكّل هذه السياسة بديلًا عنها.</p><p><strong>eurekaffeine (刘耀晨)</strong> — <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',19)])])}const m=a(o,[["render",n]]);export{f as __pageData,m as default};
